  "plans.perMonth": "மாதத்திற்கு",
  "plans.taxNoteWebsite": "பொருந்தும் வரிகள் கூடுதலாக, ஏதேனும் இருந்தால். சந்தா செலுத்துவதற்கு முன் உங்கள் சரியான மொத்தம் காட்டப்பட வேண்டும்.",
