  "plans.prelaunchCheckinOneDay": "24 மணி நேரத்திற்குள் ஏழு நாள் முன்-வெளியீட்டு முன்னோட்ட சரிபார்ப்பு",
  "plans.prelaunchCheckinThreeDays": "3 நாட்களுக்குள் ஏழு நாள் முன்-வெளியீட்டு முன்னோட்ட சரிபார்ப்பு",
  "plans.prelaunchCheckinBody": "உங்கள் ஏழு நாள் முன்னோட்ட சரிபார்ப்பு {date}. இது ஒரு நினைவூட்டல் மைல்கல் மட்டுமே: இலவச அணுகல் தொடர்கிறது, மேலும் எந்தக் கட்டணமும் திட்டமிடப்படவில்லை.",
  "plans.trialEndReminder": "உங்கள் பதிவு செய்யப்பட்ட சோதனை முடிவு {date}. கீழே உள்ள ரத்து விதிமுறைகளை மதிப்பாய்வு செய்யவும். இந்த நினைவூட்டல் திட்டமிடப்பட்ட கட்டணத்தை அல்லது கட்டண முறை கோப்பில் உள்ளது என்பதை உறுதிப்படுத்தாது.",
