  "alerts.intro": "உங்களுக்குப் பணச் செலவை ஏற்படுத்தும் விஷயங்களைக் கண்காணிக்கவும்: இருப்பு குறைதல், அலமாரிகள் காலியாதல், ஒருபோதும் நகராத அல்லது ஒருபோதும் ஸ்கேன் செய்யப்படாத இருப்பு, மற்றும் காலாவதியாகவிருக்கும் பொருட்கள். ஒவ்வொரு எச்சரிக்கையும் எத்தனை இடங்களை வேண்டுமானாலும், ஒரு வகையை, அல்லது அனைத்தையும் கண்காணிக்க முடியும்.",
