  "exports.backupFailed": "காப்புப்பிரதி தோல்வியடைந்தது",
  "exports.backupFailedDesc": "வணிகத் தரவைப் படிக்க முடியவில்லை. மீண்டும் முயற்சிக்கவும்.",
