  "import.chooseSpreadsheet": "ஒரு விரிதாளைத் தேர்ந்தெடுக்கவும்",
  "import.chooseSpreadsheetIntro": "CSV அல்லது உண்மையான Excel பணிப்புத்தகம் (.xlsx). நீங்கள் தேர்ந்தெடுக்கும் பணித்தாளின் முதல் வரிசையில் உங்கள் நெடுவரிசைப் பெயர்கள் உள்ளன. எதுவும் சேமிக்கப்படுவதற்கு முன் நீங்கள் ஒரு பணித்தாளைத் தேர்ந்தெடுத்து, நெடுவரிசைகளைப் பொருத்தி, வரிசைகளை முன்னோட்டமிட்டு, உலர் சோதனையை இயக்குவீர்கள்.",
  "import.importedResult": "{created} தயாரிப்பு இறக்குமதி செய்யப்பட்டது.",
