  "import.skippedRowsNote": "{skipped} வரிசை தவிர்க்கப்பட்டது — அவற்றைக் கோப்பில் சரிசெய்து மீண்டும் இறக்குமதி செய்யவும்; ஏற்கனவே உருவாக்கப்பட்ட தயாரிப்புகள் அப்படியே விடப்படும்.",
  "import.openingStockHere": "தொடக்க இருப்பை இங்கே வைக்கவும் (விருப்பம்)",
