  "import.receiveIntro": "ஒவ்வொரு வரிசையும் நீங்கள் தேர்ந்தெடுக்கும் இடத்தில் ஏற்கனவே கையில் உள்ளதில் ஒரு அளவைச் சேர்க்கிறது — அது ஒருபோதும் சரியான எண்ணிக்கையை அமைக்காது, ஒருபோதும் தயாரிப்பைத் திருத்தாது. ஒவ்வொரு வரியும் இயக்கப் பதிவேட்டில் பெறுதலாக எழுதப்படுகிறது.",
