  "print.selectedProducts": "{label} · {count} தயாரிப்பு தேர்ந்தெடுக்கப்பட்டது",
  "print.clearSelection": "தேர்வை நீக்கவும்",
  "print.templateIsBusiness": "{label} Business அம்சமாகும்",
  "print.supplierBlockedDesc": "வழங்குநர் ஆவணங்கள் Business திட்டத்துடன் செல்லும் — வழங்குநர்கள், கொள்வனவு மற்றும் கொள்வனவு ஆணைகள். உங்களிடம் இப்போது உள்ள அனைத்தும் தொடர்ந்து செயல்படும்.",
  "print.seeBusiness": "Business எதை உள்ளடக்கியது என்பதைப் பார்க்கவும்",
  "print.nothingToPrint": "இன்னும் அச்சிட எதுவும் இல்லை",
