  "print.returnFooter": "பணத்திருப்பத் தொகை இந்தச் செயலியில் கையால் பதிவு செய்யப்பட்டதாகும். கட்டணச் செயலி பணத்திருப்பம் எதுவும் குறிக்கப்படவில்லை. மீண்டும் இருப்பு வைக்கக் குறிக்கப்பட்ட வரிகள் மட்டுமே விற்கக்கூடிய இருப்புக்குத் திரும்பும்.",
