  "settings.footer.note": "இந்த அமைப்புகள் இந்த வணிகத்திற்கு மட்டுமே சொந்தமானவை. நீங்கள் வைத்திருக்கும் ஒவ்வொரு வணிகமும் தனது சொந்த தயாரிப்புகள், இடங்கள், விநியோகஸ்தர்கள் மற்றும் கொள்வனவு ஆர்டர்களை வைத்திருக்கும் — அவற்றுக்கிடையே செல்ல வணிக மாற்றியைப் பயன்படுத்தவும்.",
