  "settings.logout": "வெளியேறவும்",
  "settings.pastDue.body": "உங்கள் கடைசிக் கட்டணம் செல்லவில்லை. மேம்படுத்தல் பக்கத்திலிருந்து உங்கள் கட்டண முறையைப் புதுப்பிக்கவும் — Stripe அதன் சொந்த அட்டவணையில் மீண்டும் முயற்சிக்கும், உங்கள் சந்தா முன்கூட்டியே ரத்து செய்யப்படாது. என்ன செய்வது என்று உறுதியாகத் தெரியவில்லை என்றால், theluminousbookshop@outlook.com இல் ஆதரவைத் தொடர்பு கொள்ளவும்.",
  "settings.pastDue.title": "கட்டணம் தாமதமானது",
