  "settings.title": "அமைப்புகள்",
  "settings.trial.cancelKeeps": "உங்கள் சோதனையின்போது ரத்து செய்வது உங்கள் முழு 7 நாட்களையும் வைத்திருக்கும் — அணுகல் {date} அன்று முடிவடையும், உங்களுக்குக் கட்டணம் விதிக்கப்படாது.",
  "staff.access.noSeatBody": "இந்த வணிகத்திற்கு உங்கள் கணக்கிற்குப் பணியாளர் இருக்கை இல்லை, எனவே அதன் இருப்பு மூடப்பட்டுள்ளது. பணியாளர்கள் மற்றும் பாத்திரங்கள் பிரிவில் உங்களைச் சேர்க்குமாறு உரிமையாளரிடம் கேட்கவும்.",
  "staff.access.noSeatTitle": "இந்த வணிகம் உங்கள் உள்நுழைவுக்குத் திறக்கப்படவில்லை",
  "staff.access.pendingBody": "இந்த வணிகத்தில் உங்கள் மின்னஞ்சலுக்கு இன்னும் செயல்படுத்தப்படாத அழைப்பு உள்ளது. உங்கள் பணியாளர் நிலையைச் செயலில் என அமைக்குமாறு உரிமையாளரிடம் கேட்கவும். அதுவரை இங்கு எதுவும் தெரியாது.",
  "staff.access.pendingTitle": "உங்கள் அழைப்பு இன்னும் செயலில் இல்லை",
  "staff.access.signOut": "வெளியேறவும்",
  "staff.access.suspendedBody": "செயலில் உள்ள வணிகத்திற்கு ஒரு நிர்வாகி இந்தப் பணியாளர் கணக்கை இடைநிறுத்தியுள்ளார். உங்களை மீண்டும் செயலில் அமைக்குமாறு அவர்களிடம் கேட்டு, பின்னர் மீண்டும் உள்நுழையவும்.",
  "staff.access.suspendedTitle": "உங்கள் அணுகல் இடைநிறுத்தப்பட்டுள்ளது",
  "staff.addFirst": "முதல் பணியாளர் உறுப்பினரைச் சேர்க்கவும்",
  "staff.addMember": "பணியாளர் உறுப்பினரைச் சேர்க்கவும்",
  "staff.emptyBody": "ஒரு நபரைச் சேர்த்து, அவர்களுக்கு ஒரு பாத்திரத்தையும் அதனுடன் வரும் அனுமதிகளையும் கொடுங்கள், அவர்கள் இந்த வணிகத்தில் உள்நுழைய மின்னஞ்சல் மூலம் அழைக்கப்படுவார்கள்.",
  "staff.emptyTitle": "இன்னும் பணியாளர்கள் இல்லை",
  "staff.eyebrow": "குழு",
  "staff.how.p1": "ஒவ்வொரு உறுப்பினருக்கும் ஒரு பாத்திரமும் அவர்களது சொந்த அனுமதிப் பட்டியலும் உள்ளது, எனவே நீங்கள் ஒரு பாத்திரத்திலிருந்து தொடங்கி புதிய பாத்திரத்தை உருவாக்காமல் ஒரு விஷயத்தை மாற்றலாம். ஒரு பாத்திரத்தைத் திருத்துவது ஏற்கனவே அதில் உள்ள உறுப்பினர்களை மீண்டும் எழுதாது — அவர்களின் பாத்திர இயல்புநிலைகளை மீண்டும் பயன்படுத்த ஒரு உறுப்பினரைத் திறக்கவும்.",
  "staff.how.p2": "தனிப்பயன் பாத்திரங்கள் Business அம்சமாகும்: Essentials ஐந்து உள்ளமைக்கப்பட்ட பாத்திரங்களைப் பயன்படுத்துகிறது (உரிமையாளர், மேலாளர், இருப்பு எழுத்தர், விற்பனை எழுத்தர், பார்வையாளர்).",
  "staff.how.p3": "அழைப்புகள் மின்னஞ்சல் மூலம் அனுப்பப்படுகின்றன. ஒரு உறுப்பினர் ஏற்றுக்கொண்ட பின்னரே உள்நுழைய முடியும், மேலும் ஒருவரை இந்தப் பட்டியலிலிருந்து அகற்றுவது அவர்களின் பயன்பாட்டுக் கணக்கை நீக்காது.",
  "staff.how.p4": "ஒரு கடை என்பது ஒரு நபர் ஒதுக்கப்பட்ட இடமாகும். அது அவர்களின் அட்டையில் பதிவு செய்யப்படுகிறது; அவர்கள் எதைத் திறக்க முடியும் என்பது இன்னும் அவர்களின் பாத்திரம் மற்றும் அனுமதிகளால் தீர்மானிக்கப்படுகிறது.",
  "staff.how.p5": "ஒவ்வொரு நபரும் எதைத் திறக்க முடியும் என்பதை அனுமதிகள் தீர்மானிக்கின்றன: அவர்களின் பாத்திரத்திற்கு வெளியே உள்ள மெனு உருப்படிகள் மறைக்கப்படுகின்றன, மேலும் தடுக்கப்பட்ட முகவரி பக்கத்திற்குப் பதிலாக “உங்கள் பாத்திரத்தில் இல்லை” அறிவிப்பைக் காட்டுகிறது. அந்த நபர் அடுத்த முறை பயன்பாட்டை ஏற்றும்போது மாற்றம் பொருந்தும்; ஒரு உறுப்பினரை இடைநிறுத்துவது அவர்களை முற்றிலும் பூட்டிவிடும்.",
  "staff.how.p6": "நிர்வாகிகள் அனைத்துத் தரவையும் பார்க்கவும் மாற்றவும், பயன்பாட்டுப் பயனர்களையும் பாத்திரங்களையும் நிர்வகிக்கவும் முடியும், மேலும் அவர்கள் ஒருபோதும் பணியாளர் பாத்திரத்தால் வரம்பிடப்படுவதில்லை. பணியாளர் பதிவு இல்லாத ஒருவர் — புதிய வணிகத்தின் உரிமையாளர் — முழு அணுகலைத் தக்கவைக்கிறார்.",
  "staff.howTitle": "பணியாளர்களும் பாத்திரங்களும் எவ்வாறு செயல்படுகின்றன",
