  "staff.memberDialog.addButton": "பணியாளர் உறுப்பினரைச் சேர்க்கவும்",
  "staff.memberDialog.addDescription": "தொடங்குவதற்கு ஒரு பாத்திரத்தைத் தேர்ந்தெடுத்து, பின்னர் அவர்கள் அடைய வேண்டிய அல்லது அடையக் கூடாத எதையும் சரிசெய்யவும்.",
