  "inventoryLib.reversalBuildTeardown": "இந்தப் பதிவு ஒரு உருவாக்கம் அல்லது பிரித்தெடுப்பிலிருந்து வந்தது, இது பல பொருட்களை ஒரே நேரத்தில் நகர்த்தியது. அதற்குப் பதிலாக சரக்கை நேரடியாகச் சரிசெய்யவும்.",
