  "printLib.bluetoothUnavailable": "Bluetooth அச்சிடலுக்கு டெஸ்க்டாப் Chrome அல்லது Edge, அல்லது Android Chrome தேவை. இது iOS Safari இல் வேலை செய்யாது — iPhone இல், AirPrint உடன் Wi-Fi வழியாக அச்சிடவும், அல்லது மொபைல் பயன்பாட்டிலிருந்து Bluetooth ஐப் பயன்படுத்தவும் (மொபைல் பயன்பாட்டுடன் வருகிறது).",
  "printLib.usbUnavailable": "வலைத்தளத்திலிருந்து USB அச்சிடலுக்கு Android Chrome மற்றும் USB OTG கேபிள் தேவை. டெஸ்க்டாப்பில், அச்சுப்பொறியை கணினியில் செருகி அச்சிடு பொத்தானைப் பயன்படுத்தவும் — அது அங்கே நிறுவப்பட்ட அச்சுப்பொறி மூலம் அச்சிடும். iPhone கள் USB வழியாக நேரடியாக அச்சிட முடியாது — AirPrint உடன் Wi-Fi ஐப் பயன்படுத்தவும், அல்லது மொபைல் பயன்பாட்டிலிருந்து Bluetooth ஐப் பயன்படுத்தவும் (மொபைல் பயன்பாட்டுடன் வருகிறது).",
